#!/usr/bin/env python3n"""nExample script showing how to use the TableSizeCalculator class programmatically.nnThis example demonstrates:n- Creating a custom Spark sessionn- Using the calculator with custom configurationn- Processing specific databases onlyn- Custom output handlingn"""nnimport jsonnimport loggingnfrom table_size_calculator import TableSizeCalculator, create_spark_sessionnnndef main():n    """Example usage of TableSizeCalculator."""n    n    # Custom configurationn    config = {n        'app_name': 'ExampleTableSizeCalculator',n        'log_level': 'INFO',n        'spark_configs': {n            'spark.sql.adaptive.enabled': 'true',n            'spark.sql.adaptive.coalescePartitions.enabled': 'true'n        }n    }n    n    # Create Spark sessionn    spark = create_spark_session(config)n    n    try:n        # Initialize calculatorn        calculator = TableSizeCalculator(spark, config)n        n        # Example 1: Get all databasesn        print("=== Available Databases ===")n        databases = calculator.get_all_databases()n        for db in databases[:5]:  # Show first 5n            print(f"- {db}")n        n        # Example 2: Analyze specific databasen        if databases:n            target_db = databases[0]  # Use first databasen            print(f"\n=== Tables in {target_db} ===")n            tables = calculator.get_tables_in_database(target_db)n            for db_name, table_name in tables[:3]:  # Show first 3n                print(f"- {db_name}.{table_name}")n        n        # Example 3: Get size info for a specific tablen        if databases and tables:n            db_name, table_name = tables[0]n            print(f"\n=== Size Info for {db_name}.{table_name} ===")n            table_info = calculator.get_table_size_info(db_name, table_name)n            if table_info:n                print(f"Rows: {table_info.row_count:,}")n                print(f"Size: {table_info.data_size_gb:.2f} GB")n                print(f"Location: {table_info.location}")n        n        # Example 4: Calculate sizes for all tables (commented out for demo)n        # print("\n=== Calculating All Table Sizes ===")n        # all_sizes = calculator.calculate_all_table_sizes()n        # print(f"Processed {len(all_sizes)} tables")n        n    except Exception as e:n        logging.error(f"Example failed: {str(e)}")n    finally:n        spark.stop()nnnif __name__ == "__main__":n    main()